                truth_table[j][i] = 1 if sum([sat_formula[k][(i >> k) & 1] for k in range(n)]) >= 1 else 0
        matrix = []
        for row in truth_table:
            matrix.append(row + [sum(row)])
        rank = 0
        for i in range(n):
            if matrix[i][n]:
                rank += 1
                for j in range(i+1, n):
                    if matrix[j][n]:
                        factor = matrix[j][i] / matrix[i][i]
                        for k in range(n + 1):
